    {"cap":"冶炼厂高负荷11/33kV成套开关设备+E-house+绿电并网升压","capKbd":null,"capKm":null,"capMW":null,"capMWh":null,"capMva":null,"capPF":null,"capPax":null,"capTeu":null,"capVeh":null,"capWafer":null,"capWty":null,"cat":"client","coord":[136.88,-30.44],"country":"澳大利亚","desc":"奥林匹克坝冶炼精炼厂高负荷配电,E-house成套开关+绿电PPA并网。","detail":"奥林匹克坝是必和必拓南澳铜矿省核心,集采矿、冶炼、精炼于一体,2029年7月起接入Neoen戈伊德北100MW 7×24基荷绿电PPA,目标2030年南澳约70%用电转绿。冶炼炉、电解精炼与铀回收为大功率连续高负荷,对配电可靠性、谐波治理与无功补偿要求极高。特锐德可提供冶炼厂11/33kV中压成套开关设备与E-house防护型配电单元(工厂预制、整体运输、现场即插即用,适配南澳偏远矿区施工条件与AS标准),以及绿电PPA接入侧的升压并网舱,支撑其冶炼扩容与脱碳供电改造。","en":"BHP Olympic Dam Cu-Au-U Smelter High-Load Distribution (E-house)","epc":"供配电设备商机条目，无独立EPC(业主框架采购)","epcStatus":"不适用","id":7302,"inv":2.6,"invText":"约 2.6 亿美元（特锐德设备包估算）","name":"必和必拓 南澳奥林匹克坝铜金铀冶炼厂高负荷配电(E-house)","owner":"必和必拓 / BHP","region":"大洋洲","status":"在建","sub":"bhp","updated":"2026-06","year":2029},
    {"cap":"矿区光储微网+预制舱变电站+储能并网舱+E-house配电","capKbd":null,"capKm":null,"capMW":null,"capMWh":null,"capMva":null,"capPF":null,"capPax":null,"capTeu":null,"capVeh":null,"capWafer":null,"capWty":null,"cat":"client","coord":[137.95,-31.27],"country":"澳大利亚","desc":"两座地下铜矿偏远离网,光储微网+预制舱变电站保稳定供电。","detail":"Carrapateena与Prominent Hill是必和必拓2023年并购OZ Minerals后纳入南澳铜矿省的两座地下铜矿,地处偏远、网架薄弱,同样纳入戈伊德北7×24基荷绿电供电范围。地下提升、通风与选矿连续负荷在弱网末端易受电压波动影响,亟需就地光储微网平抑波动、离网保供。值得一提的是Prominent Hill 110kV整站(110kV HGIS+10kV E-House)是特锐德海外首个EPC项目,已积累AS3000/NBC经验。特锐德可在此基础上提供矿区光储微网的储能并网舱、预制舱升压站与E-house防护型配电,实现弱网末端的稳定保供与离网应急。","en":"BHP Carrapateena & Prominent Hill Copper Mine Microgrid (Off-grid Solar-Storage)","epc":"供配电设备商机条目，无独立EPC(业主框架采购)","epcStatus":"不适用","id":7303,"inv":1.8,"invText":"约 1.8 亿美元（特锐德设备包估算）","name":"必和必拓 南澳Carrapateena与Prominent Hill铜矿微网(光储离网)","owner":"必和必拓 / BHP","region":"大洋洲","status":"在建","sub":"bhp","updated":"2026-06","year":2028},
    {"cap":"港口33/132kV预制舱升压站+岸电中压配电+风光储绿电并网舱","capKbd":null,"capKm":null,"capMW":null,"capMWh":null,"capMva":null,"capPF":null,"capPax":null,"capTeu":null,"capVeh":null,"capWafer":null,"capWty":null,"cat":"client","coord":[118.6,-20.31],"country":"澳大利亚","desc":"皮尔巴拉WAIO铁矿黑德兰港岸电与绿电并网,预制舱升压+中压配电。","detail":"必和必拓西澳铁矿(WAIO)以黑德兰港(Port Hedland)为出口枢纽,正采购逾500MW风光储绿电替代柴油与天然气,2024年底已通过与Alinta的绿电PPA使港口用电排放减半,并推进矿卡电气化与岸电改造。港口装船机、堆取料机与岸电系统为大容量冲击性负荷,绿电接入需要灵活升压并网。特锐德可提供港口33/132kV模块化预制舱升压站、岸电与皮带廊的中压成套开关设备,以及风光储绿电接入的储能并网舱——预制舱抗皮尔巴拉高温、热带气旋与盐雾,工厂集成快速部署,契合其2030年运营减排30%目标。","en":"BHP WAIO Pilbara Iron Ore Port Hedland Power Supply (E-house Substation)","epc":"供配电设备商机条目，无独立EPC(业主框架采购)","epcStatus":"不适用","id":7304,"inv":2.2,"invText":"约 2.2 亿美元（特锐德设备包估算）","name":"必和必拓 西澳皮尔巴拉WAIO铁矿黑德兰港供配电(预制舱升压)","owner":"必和必拓 / BHP","region":"大洋洲","status":"规划","sub":"bhp","updated":"2026-06","year":2030},
    {"cap":"33kV车载移动变电站+矿区光储微网并网舱","capKbd":null,"capKm":null,"capMW":null,"capMWh":null,"capMva":null,"capPF":null,"capPax":null,"capTeu":null,"capVeh":null,"capWafer":null,"capWty":null,"cat":"client","coord":[117.79,-22.69],"country":"澳大利亚","desc":"为西澳皮尔巴拉多矿区铁矿配置车载移动变电站与并网储能舱，支撑选厂检修保供与风光绿电接入。","detail":"力拓在西澳皮尔巴拉运营汤姆普莱斯、帕拉布杜等多座大型铁矿，正推进风光储绿电替代柴油、降低运营排放。矿区分散、检修期破碎选矿负荷不可长时间中断，且大量原住民合资光伏(如Jinbi)需快速并网消纳。特锐德可切入：①33kV车载移动变电站在固定变电站检修或故障时滚动接力供电，避免选厂停产；②储能并网舱+中低压成套开关柜支撑风光绿电平滑接入、稳定矿区弱电网频率；③预制舱降压站缩短偏远矿点的电气化部署周期，适配皮尔巴拉高温干热环境。","en":"Rio Tinto Pilbara Iron Ore Mobile Substation Emergency Power (W Australia)","epc":"供配电设备商机条目，无独立EPC(业主框架采购)","epcStatus":"不适用","id":7312,"inv":1.6,"invText":"约 1.6 亿美元(设备包估算)","name":"力拓 西澳皮尔巴拉铁矿车载移动变应急保供电","owner":"力拓(Rio Tinto)","region":"大洋洲","status":"规划","sub":"riotinto","updated":"2026-06","year":2028},
    {"cap":"矿区33/132kV预制舱升压站群 + 多台车载移动变电站 + 中压成套开关柜","capKbd":null,"capKm":null,"capMW":null,"capMWh":null,"capMva":null,"capPF":null,"capPax":null,"capTeu":null,"capVeh":null,"capWafer":null,"capWty":null,"cat":"client","coord":[119.95,-22.36],"country":"澳大利亚","desc":"福特斯库皮尔巴拉云断/圣诞溪/所罗门铁矿群供配电与车载移动变快速恢复供电机会，特锐德预制舱升压站+移动变切入。","detail":"福特斯库在西澳皮尔巴拉运营云断(Cloudbreak)、圣诞溪(Christmas Creek)、所罗门(Solomon)等多座超大型铁矿，选矿厂、破碎站、矿卡快充与远程操控中心构成连续高负荷,任何停电都直接中断年逾亿吨的铁矿外运。供配电需求集中在33/132kV矿区升压与多点中压配电，以及检修/扩产/事故时的快速恢复供电。特锐德可提供模块化预制舱式升压站(工厂预制、运抵即装，缩短偏远矿区建设周期)、车载移动变电站(在主变检修或故障时数小时内进场顶替、保障选矿厂不停产)及中低压成套开关设备，配合矿卡电气化负荷增长滚动扩容。","en":"Fortescue Pilbara Iron Ore Hubs Power Supply & Mobile Substation Backup","epc":"供配电设备商机条目，无独立EPC(业主框架采购)","epcStatus":"不适用","id":7320,"inv":2.6,"invText":"约 2.6 亿美元（特锐德设备包估算）","name":"福特斯库 西澳皮尔巴拉铁矿群供配电(车载移动变保供电)","owner":"福特斯库（Fortescue / FMG）","region":"大洋洲","status":"投运","sub":"fortescue","updated":"2026-06","year":2025},
    {"cap":"选矿厂E-house防护型配电站 + 11/33kV成套开关设备 + 移动变备用","capKbd":null,"capKm":null,"capMW":null,"capMWh":null,"capMva":null,"capPF":null,"capPax":null,"capTeu":null,"capVeh":null,"capWafer":null,"capWty":null,"cat":"client","coord":[118.6,-21.5],"country":"澳大利亚","desc":"福特斯库铁桥磁铁矿选矿/磨矿高耗电环节配电机会，特锐德E-house防护型一体化配电站切入。","detail":"铁桥(Iron Bridge)磁铁矿由福特斯库与台塑合资，年产高品位磁精矿约2200万吨，磨矿、磁选、管道输送等工序耗电强度远高于普通赤铁矿，2025年持续爬坡上量对供电稳定性与扩容弹性要求极高。皮尔巴拉高温、粉尘、盐雾环境对户外配电设备防护是硬约束。特锐德E-house(集成式电气小室)可在工厂内完成开关柜、变压器、保护与监控的预装预调，整体吊装到位，IP防护与隔热设计适配恶劣矿区工况;配套11/33kV中压成套开关设备服务磨机/泵站大功率电机，并以移动变电站作为关键负荷的应急备用。","en":"Fortescue Iron Bridge Magnetite Processing High-Load Distribution (E-house)","epc":"商机条目；底层铁桥项目为业主多包(湿选厂SIMPEC+CPB、干选厂Civmec等)","epcStatus":"已授标","id":7321,"inv":1.8,"invText":"约 1.8 亿美元（特锐德设备包估算）","name":"福特斯库 铁桥磁铁矿冶选高负荷配电(E-house防护型)","owner":"福特斯库（Fortescue / FMG）/ 台塑","region":"大洋洲","status":"投运","sub":"fortescue","updated":"2026-06","year":2025},
    {"cap":"光储升压并网舱 + 储能并网舱 + 132kV预制舱开关站(配629km输电网)","capKbd":null,"capKm":629,"capMW":null,"capMWh":null,"capMva":null,"capPF":null,"capPax":null,"capTeu":null,"capVeh":null,"capWafer":null,"capWty":null,"cat":"client","coord":[120.28,-21.33],"country":"澳大利亚","desc":"福特斯库PEC风光储输电骨干网的升压并网与储能并网设备机会，特锐德储能并网舱+预制舱开关站切入。","detail":"皮尔巴拉能源连接(PEC)是福特斯库构建的可再生能源生态:太阳能、风电、电池储能加一张629公里输电网络，计划2030年部署2-3GW风光储以彻底消除铁矿运营化石燃料，并已交付North Star 100MW光伏与50MW/250MWh电池。海量分布式光储要接入矿区微网,升压、并网与开关站需求密集。特锐德可提供光储升压并网舱、储能并网舱(集成PCS接口、并网保护与监控,平抑光伏波动、支撑离网/弱网微网稳定)及132kV级模块化预制舱开关站,服务PEC输电骨干的分段建设;模块化交付契合矿区点多面广、工期紧的特点。","en":"Fortescue Pilbara Energy Connect Solar-Storage Microgrid Step-up & Grid Connection","epc":"业主自主交付；输电/电气总包：GenusPlus","epcStatus":"已授标","id":7323,"inv":2.2,"invText":"约 2.2 亿美元（特锐德设备包估算）","name":"福特斯库 皮尔巴拉能源连接PEC光储微网升压并网","owner":"福特斯库（Fortescue）","region":"大洋洲","status":"在建","sub":"fortescue","updated":"2026-06","year":2026},
    {"cap":"铜/锌冶炼厂E-house成套配电 + 移动变应急","capKbd":null,"capKm":null,"capMW":null,"capMWh":null,"capMva":null,"capPF":null,"capPax":null,"capTeu":null,"capVeh":null,"capWafer":null,"capWty":null,"cat":"client","coord":[139.49,-20.72],"country":"澳大利亚","desc":"昆士兰芒特艾萨铜锌冶炼枢纽转加工第三方精矿，TGOOD冶炼厂E-house防护配电+移动应急变。","detail":"嘉能可昆士兰芒特艾萨(Mount Isa)地下铜矿2025年关停后,铜冶炼厂转为加工第三方精矿、锌业以乔治费舍尔矿延寿至2042年,园区集中了铜锌冶炼、酸厂等连续高负荷工艺,对供电连续性与配电设备耐受冶炼粉尘/腐蚀环境要求极高。特锐德可切入点:以E-house防护型成套配电(防尘、防腐、整体集成、工厂预制运输至偏远内陆)替代现场土建电气房,服务冶炼、酸厂与公辅车间;以中低压成套开关设备完成大功率电机与整流负荷分区配电;部署车载移动变作为冶炼连续生产的应急备用电源,避免停炉事故损失。","en":"Glencore Mount Isa (Australia) Smelter High-Load Distribution","epc":"供配电设备商机条目，无独立EPC(业主框架采购)","epcStatus":"不适用","id":7333,"inv":1.2,"invText":"约 1.2 亿美元（设备包估算）","name":"嘉能可 澳洲Mount Isa冶炼厂高负荷配电","owner":"Glencore（嘉能可，Mount Isa Mines）","region":"大洋洲","status":"投运","sub":"glencore","updated":"2026-06","year":2026},
    {"cap":"150MW/600MWh 储能(168台特斯拉Megapack 2XL)","capKbd":null,"capKm":null,"capMW":150,"capMWh":600,"capMva":null,"capPF":null,"capPax":null,"capTeu":null,"capVeh":null,"capWafer":null,"capWty":null,"cat":"storage","coord":[143.85,-37.75],"country":"澳大利亚","desc":"紧邻南半球最大风电场，四小时时长大电池2026年初开工","descEn":"Four-hour big battery next to the Southern Hemisphere's largest wind farm, construction started early 2026","detail":"位于澳大利亚维多利亚州吉朗西北约60公里的金原野风电场旁，紧邻在建的1.33GW金原野风电场(南半球最大风电场)。葡萄牙开发商 TagEnergy 于 2025 年 11 月完成融资、2026 年初开工建设该 150MW/600MWh(四小时时长)电池储能系统，采用 168 台特斯拉 Megapack 2XL，为 TagEnergy 在澳的首个储能项目。建设期约两年，计划 2027—2028 年建成投运，为维州电网提供调峰与稳定支撑。","detailEn":"About 60 km north-west of Geelong, Victoria, Australia, next to the 1.33 GW Golden Plains Wind Farm (the Southern Hemisphere's largest). Portugal-based developer TagEnergy secured financial close in November 2025 and began construction in early 2026 on the 150MW/600MWh (four-hour) battery, using 168 Tesla Megapack 2XL units and marking its first Australian storage project. Construction takes about two years, with completion targeted for 2027-2028, providing firming and peaking support to the Victorian grid.","en":"Golden Plains Battery Energy Storage System","epc":"BoP总包：CPP；电池 Tesla Megapack 2XL(168台)","epcStatus":"已授标","flagship":false,"id":7420,"inv":3,"invText":"约3亿美元(估)","name":"金原野大电池储能(Golden Plains BESS)","owner":"TagEnergy","region":"大洋洲","status":"在建","sub":"liion","updated":"2026-06","year":2027},
    {"cap":"50MW/250MWh 储能(五小时时长)","capKbd":null,"capKm":null,"capMW":50,"capMWh":250,"capMva":null,"capPF":null,"capPax":null,"capTeu":null,"capVeh":null,"capWafer":null,"capWty":null,"cat":"storage","coord":[138.9,-33.4],"country":"澳大利亚","desc":"南澳燃气电站旁配套储能，2026年2月融资完成开工","descEn":"Storage co-located with a South Australia gas plant, financial close and delivery start February 2026","detail":"位于澳大利亚南澳州戈伊德(Goyder)地区，EnergyAustralia 的 50MW/250MWh(五小时时长)哈利特电池储能一期与既有 235MW 燃气电站同址建设，于 2026 年 2 月 13 日达成融资完成并启动交付。项目由 NHOA Energy 担任电池集成商、Enerven 承担土建与电气施工，随后数周内开工，预计 2027 年年中投入商业运营，利用现有并网点为南澳电网提供调峰与稳定支撑。二期(200MW/1000MWh)已获规划批准。","detailEn":"In the Goyder region of South Australia, EnergyAustralia's 50MW/250MWh (five-hour) Hallett battery Stage 1 is co-located with an existing 235MW gas-fired power station. It reached financial close on 13 February 2026 and moved into delivery, with NHOA Energy as battery integrator and Enerven handling civil and electrical works; construction starts within weeks and commercial operation is expected by mid-2027, using the existing grid connection to firm the SA grid. A Stage 2 (200MW/1,000MWh) already has planning approval.","en":"Hallett Battery Energy Storage System Stage 1","epc":"EPC：NHOA Energy；BoP施工：Enerven","epcStatus":"已授标","flagship":false,"id":7421,"inv":1.5,"invText":"约1.5亿美元(估)","name":"哈利特电池储能一期(Hallett BESS Stage 1)","owner":"EnergyAustralia / NHOA Energy / Enerven","region":"大洋洲","status":"在建","sub":"liion","updated":"2026-02","year":2027},
    {"cap":"一期200MW光伏+275MW/2200MWh八小时储能（全规模435MW光伏+475MW/3148MWh）","capKbd":null,"capKm":null,"capMW":200,"capMWh":5348,"capMva":null,"capPF":null,"capPax":null,"capTeu":null,"capVeh":null,"capWafer":null,"capWty":null,"cat":"renewable","coord":[153,-29.2],"country":"澳大利亚","desc":"2026年7月21日高丽亚铅董事会批准FID：A$13亿一期200MW光伏+2200MWh八小时长时储能，10月开工","descEn":"Korea Zinc's board approved FID on 21 Jul 2026 for Ark Energy's A$1.3bn Richmond Valley stage 1 — 200 MWac solar + 275 MW/2,200 MWh 8-hour BESS in NSW; construction from Oct 2026.","detail":"高丽亚铅（Korea Zinc）董事会2026年7月21日在首尔批准旗下 Ark Energy 里士满谷（Richmond Valley）光储项目的最终投资决定：项目位于新南威尔士州卡西诺以南25公里，一期投资约13亿澳元，建设200MWac光伏配套275MW/2200MWh八小时长时磷酸铁锂储能（获NSW长时储能LTESA支持），全规模规划435MW光伏+475MW/3148MWh储能。计划2026年9月完成金融关闭、10月开工。项目绿电将支撑高丽亚铅旗下汤斯维尔锌冶炼厂脱碳与集团绿色金属战略。","detailEn":"On 21 July 2026 Korea Zinc's board in Seoul approved the final investment decision for Ark Energy's Richmond Valley project, 25 km south of Casino in NSW: an approximately A$1.3 billion stage 1 comprising a 200 MWac solar farm co-located with a 275 MW / 2,200 MWh eight-hour LFP battery (backed by an NSW LTESA), within a fully approved configuration of 435 MW solar + 475 MW / 3,148 MWh. Financial close is targeted for September 2026 with construction starting October, supplying green power toward Korea Zinc's Townsville refinery decarbonisation.","en":"Richmond Valley Solar Farm & BESS (Ark Energy)","epc":"EPC 安排未公开（2026-09 金融关闭、2026-10 开工）","epcStatus":"未公开","flagship":false,"id":7509,"inv":9.1,"invText":"约 A$13 亿（约$9.1亿）","name":"Ark Energy 里士满谷光储项目（新州）","owner":"Ark Energy（高丽亚铅 Korea Zinc 旗下）","region":"大洋洲","status":"规划","sub":"solar","updated":"2026-07","year":2028}
